class KB:
    """protocol KB: message classes by method number, and its Client and Handler."""

    REQUESTS = {
        1: GetEntitiesRequest,
        2: PutEntitiesRequest,
        3: MergeRequest,
        4: DestroyRequest,
        5: FindByLabelRequest,
        6: FindByValueRequest,
        7: FindLinksRequest,
        8: InstancesRequest,
        9: WatchRequest,
        10: UnwatchRequest,
    }

    RESPONSES = {
        1: GetEntitiesResponse,
        2: PutEntitiesResponse,
        3: MergeResponse,
        4: DestroyResponse,
        5: FindByLabelResponse,
        6: FindByValueResponse,
        7: FindLinksResponse,
        8: InstancesResponse,
        9: WatchResponse,
        10: UnwatchResponse,
    }

    class Client(system.Client):
        """protocol KB: client, for a handle to a service."""

        def get_entities(self,
                         ids: list[str] | None = None,
                         follow: bool = False,
                         languages: list[str] | None = None) -> GetEntitiesResponse:
            """KB.GetEntities."""
            request = GetEntitiesRequest(ids=ids, follow=follow, languages=languages)
            return self.call(request, GetEntitiesResponse)

        def put_entities(self, entities: list[Entity] | None = None) -> PutEntitiesResponse:
            """KB.PutEntities."""
            return self.call(PutEntitiesRequest(entities=entities), PutEntitiesResponse)

        def merge(self, old_id: str = '', new_id: str = '') -> MergeResponse:
            """KB.Merge."""
            return self.call(MergeRequest(old_id=old_id, new_id=new_id), MergeResponse)

        def destroy(self, entity_id: str = '') -> DestroyResponse:
            """KB.Destroy."""
            return self.call(DestroyRequest(entity_id=entity_id), DestroyResponse)

        def find_by_label(self,
                          text: str = '',
                          language: str = '',
                          match: Match = Match.EXACT,
                          class_id: str = '',
                          max: int = 0,
                          after: str = '') -> FindByLabelResponse:
            """KB.FindByLabel."""
            request = FindByLabelRequest(text=text,
                                         language=language,
                                         match=match,
                                         class_id=class_id,
                                         max=max,
                                         after=after)
            return self.call(request, FindByLabelResponse)

        def find_by_value(self,
                          property_id: str = '',
                          value: str = '',
                          max: int = 0,
                          after: str = '') -> FindByValueResponse:
            """KB.FindByValue."""
            request = FindByValueRequest(property_id=property_id, value=value, max=max, after=after)
            return self.call(request, FindByValueResponse)

        def find_links(self,
                       target_id: str = '',
                       property_id: str = '',
                       role: Role = Role.MAIN,
                       max: int = 0,
                       after: str = '') -> FindLinksResponse:
            """KB.FindLinks."""
            request = FindLinksRequest(target_id=target_id,
                                       property_id=property_id,
                                       role=role,
                                       max=max,
                                       after=after)
            return self.call(request, FindLinksResponse)

        def instances(self, class_id: str = '', max: int = 0, after: str = '') -> InstancesResponse:
            """KB.Instances."""
            request = InstancesRequest(class_id=class_id, max=max, after=after)
            return self.call(request, InstancesResponse)

        def watch(self, ids: list[str] | None = None, listener: int | None = None) -> WatchResponse:
            """KB.Watch."""
            return self.call(WatchRequest(ids=ids, listener=listener), WatchResponse)

        def unwatch(self, watch_id: int = 0) -> UnwatchResponse:
            """KB.Unwatch."""
            return self.call(UnwatchRequest(watch_id=watch_id), UnwatchResponse)

    class Handler(system.Handler):
        """protocol KB: base class for a service's handler."""

        METHODS = {
            1: (GetEntitiesRequest, "get_entities"),
            2: (PutEntitiesRequest, "put_entities"),
            3: (MergeRequest, "merge"),
            4: (DestroyRequest, "destroy"),
            5: (FindByLabelRequest, "find_by_label"),
            6: (FindByValueRequest, "find_by_value"),
            7: (FindLinksRequest, "find_links"),
            8: (InstancesRequest, "instances"),
            9: (WatchRequest, "watch"),
            10: (UnwatchRequest, "unwatch"),
        }

        def get_entities(self,
                         request: GetEntitiesRequest,
                         source: int) -> GetEntitiesResponse | system.Deferred:
            """Handle KB.GetEntities."""
            raise NotImplementedError

        def put_entities(self,
                         request: PutEntitiesRequest,
                         source: int) -> PutEntitiesResponse | system.Deferred:
            """Handle KB.PutEntities."""
            raise NotImplementedError

        def merge(self, request: MergeRequest, source: int) -> MergeResponse | system.Deferred:
            """Handle KB.Merge."""
            raise NotImplementedError

        def destroy(self,
                    request: DestroyRequest,
                    source: int) -> DestroyResponse | system.Deferred:
            """Handle KB.Destroy."""
            raise NotImplementedError

        def find_by_label(self,
                          request: FindByLabelRequest,
                          source: int) -> FindByLabelResponse | system.Deferred:
            """Handle KB.FindByLabel."""
            raise NotImplementedError

        def find_by_value(self,
                          request: FindByValueRequest,
                          source: int) -> FindByValueResponse | system.Deferred:
            """Handle KB.FindByValue."""
            raise NotImplementedError

        def find_links(self,
                       request: FindLinksRequest,
                       source: int) -> FindLinksResponse | system.Deferred:
            """Handle KB.FindLinks."""
            raise NotImplementedError

        def instances(self,
                      request: InstancesRequest,
                      source: int) -> InstancesResponse | system.Deferred:
            """Handle KB.Instances."""
            raise NotImplementedError

        def watch(self, request: WatchRequest, source: int) -> WatchResponse | system.Deferred:
            """Handle KB.Watch."""
            raise NotImplementedError

        def unwatch(self,
                    request: UnwatchRequest,
                    source: int) -> UnwatchResponse | system.Deferred:
            """Handle KB.Unwatch."""
            raise NotImplementedError


class Listener:
    """protocol Listener: message classes by method number, and its Client and Handler."""

    REQUESTS = {
        1: Changed,
    }

    RESPONSES = {}

    class Client(system.Client):
        """protocol Listener: client, for a handle to a service."""

        def changed(self, entity_id: str = '', revision: int = 0) -> None:
            """Listener.Changed, one-way."""
            self.send(Changed(entity_id=entity_id, revision=revision))

    class Handler(system.Handler):
        """protocol Listener: base class for a service's handler."""

        METHODS = {
            1: (Changed, "changed"),
        }

        def changed(self, request: Changed, source: int) -> None:
            """Handle Listener.Changed, one-way."""
            raise NotImplementedError
